    fun pendingClaimCandidates(): List<ClaimRow>
    /** Serves refinement StaleClaim — `StaleClaim`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun staleClaimCandidates(submittedAtBefore: Instant): List<ClaimRow>
    /** Serves rule RemindLicence — `LicenceExpiringSoon where not (exists (LicenceReminder where (pharmacist == this) and (sentOn > (today - 7 days))))`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun remindLicenceCandidates(sentOnAfter: LocalDate): List<StaffRow>
    /** Serves rule QuarantineExpired — `ExpiredLot where (onHand > 0) and (not (exists Quarantine for this))`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun quarantineExpiredCandidates(expiresOnBefore: LocalDate): List<StockLotRow>
    /** Serves rule QuarantineRecalled — `RecalledLot where not (exists Quarantine for this)`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun quarantineRecalledCandidates(): List<StockLotRow>
    /** Serves rule NoticeRecall — `Fill where (lot is RecalledLot) and (not (exists RecallNotice for this))`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun noticeRecallCandidates(): List<FillRow>
    /** Serves rule Reorder — `LowStock where not (exists OpenPurchaseOrder for this)`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun reorderCandidates(): List<DrugRow>
    /** Serves rule AlertAllergy — `AllergyConflict where not (exists (PharmacistAlert where (prescription == this) and (kind == "allergy")))`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun alertAllergyCandidates(): List<PrescriptionRow>
    /** Serves rule AlertInteraction — `InteractionConflict where not (exists (PharmacistAlert where (prescription == this) and (kind == "interaction")))`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun alertInteractionCandidates(): List<PrescriptionRow>
    /** Serves rule LogControlled — `Fill where lot.drug is Controlled`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun logControlledCandidates(): List<FillRow>
    /** Serves rule AlertCounter — `ReadyForPickup where (prescription is AllergyConflict) and (not (exists CounterAlert for this))`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun alertCounterCandidates(): List<FillRow>
    /** Serves rule AskPrescriber — `RefillRefusal where (reason == "no refills remaining") and (not (exists AuthorisationRequest for prescription))`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun askPrescriberCandidates(): List<RefillRefusalRow>
    /** Serves rule NagRefillTask — `OverdueRefillTask where not (exists (TaskNag where (task == this) and (sentOn == today)))`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun nagRefillTaskCandidates(requestedOnBefore: LocalDate, sentOnIs: LocalDate): List<RefillTaskRow>
    /** Serves rule SubmitClaim — `InsuredFill where not (exists Claim for this)`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun submitClaimCandidates(): List<FillRow>
    /** Serves rule FollowUpClaim — `StaleClaim where not (exists (ClaimFollowUp where (claim == this) and (followedUpAt > (now - 24 hours))))`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun followUpClaimCandidates(submittedAtBefore: Instant, followedUpAtAfter: Instant): List<ClaimRow>
    /** Serves never #1 — `Staff where ((role != "pharmacist") and (role != "technician")) and (role != "admin")`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never1Candidates(): List<StaffRow>
    /** Serves never #2 — `LicenceRenewal where pharmacist is not Pharmacist`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never2Candidates(): List<LicenceRenewalRow>
    /** Serves never #3 — `Drug where ((schedule < 0) or (schedule == 1)) or (schedule > 5)`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never3Candidates(): List<DrugRow>
    /** Serves never #5 — `Interaction where (severity != "major") and (severity != "moderate")`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never5Candidates(): List<InteractionRow>
    /** Serves never #6 — `PriceChange where unitPrice < 0`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never6Candidates(): List<PriceChangeRow>
    /** Serves never #11 — `StockLot where received <= 0`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never11Candidates(): List<StockLotRow>
    /** Serves never #14 — `PrescriberOrder where writtenOn > today`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never14Candidates(writtenOnAfter: LocalDate): List<PrescriberOrderRow>
    /** Serves never #15 — `Prescription where quantity <= 0`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never15Candidates(): List<PrescriptionRow>
    /** Serves never #16 — `Prescription where daysSupply <= 0`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never16Candidates(): List<PrescriptionRow>
    /** Serves never #17 — `Prescription where refillsAuthorized < 0`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never17Candidates(): List<PrescriptionRow>
    /** Serves never #18 — `Prescription where (drug is ScheduleTwo) and (refillsAuthorized > 0)`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never18Candidates(): List<PrescriptionRow>
    /** Serves never #19 — `Prescription where (drug is Controlled) and (refillsAuthorized > 5)`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never19Candidates(): List<PrescriptionRow>
    /** Serves never #22 — `ConflictOverride where pharmacist is not Pharmacist`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never22Candidates(): List<ConflictOverrideRow>
    /** Serves never #28 — `MonitoringCheck where pharmacist is not Pharmacist`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never28Candidates(): List<MonitoringCheckRow>
    /** Serves never #34 — `Counselling where pharmacist is not Pharmacist`.
     *  Superset contract: any superset of the matching rows is correct. */
    fun never34Candidates(): List<CounsellingRow>

    // ── capture memory: null when no current membership (README §13) ──
    fun readyForPickupCapture(instance: Ref.Persisted): ReadyForPickupCapture?
}

